        head: String(parsed.head),
        verdict: verdict,
        blocking: Number(parsed.blocking || 0) || 0,
        important: Number(parsed.important || 0) || 0,
        suggestions: Number(parsed.suggestions || 0) || 0,
        at: String(parsed.at || ''),
        source: String(parsed.source || 'unknown')
