/**
 * Tracker-aware comment markup helpers.
 *
 * Post-action templates historically hard-code Jira wiki markup
 * (`h3.`, `{code}`, `*bold*`, `[text|url]`). When the ticket lives on
 * GitHub Issues (key shapes `gh-12`, `owner/repo#12`, `#12`, bare `12` —
 * owned by common/ticketKeyShapes.js) those comments render as noise. These helpers render each construct in
 * the flavor of the ticket's tracker: Jira wiki for Jira keys, Markdown
 * for GitHub keys — with an explicit override via
 * `customParams.commentMarkup` (`'jira' | 'markdown'`, `'github'` is
 * accepted as an alias for `'markdown'`).
 *
 * Usage:
 *   var commentMarkup = require('./common/commentMarkup.js');
 *   var m = commentMarkup.forTicket(ticketKey, customParams);
 *   var comment = m.h(3, 'Development Completed') + '\n\n' +
 *       m.bold('Branch:') + ' ' + m.inline(branchName) + '\n';
 *
 * The Jira flavor output is byte-identical to the historical templates,
 * so Jira-facing behavior is unchanged.
 */
'use strict';

var ticketKeyShapes = require('./ticketKeyShapes.js');

function flavorForTicket(ticketKey, customParams) {
    var explicit = customParams && customParams.commentMarkup;
    if (typeof explicit === 'string' && explicit) {
        var norm = explicit.toLowerCase();
        if (norm === 'markdown' || norm === 'github') return 'markdown';
        if (norm === 'jira') return 'jira';
    }
    // Key shapes come from the single owner (gh-770): common/ticketKeyShapes.js.
    if (ticketKeyShapes.isGitHubKeyShape(ticketKey)) return 'markdown';
    return 'jira';
}

function markdownFlavor() {
    return {
        h: function (level, text) {
            var prefix = '';
            for (var i = 0; i < level; i++) prefix += '#';
            return prefix + ' ' + text;
        },
        bold: function (text) { return '**' + text + '**'; },
        italic: function (text) { return '_' + text + '_'; },
        inline: function (text) { return '`' + text + '`'; },
        code: function (text, lang) {
            return '```' + (lang || '') + '\n' + text + '\n```';
        },
        link: function (text, url) { return '[' + text + '](' + url + ')'; },
        panel: function (title, body, jiraOpts) {
            var header = title ? '> **' + title + '**\n>\n' : '';
            var quoted = String(body).split('\n').map(function (line) {
                return '> ' + line;
            }).join('\n');
            return header + quoted;
        }
    };
}

function jiraFlavor() {
    return {
        h: function (level, text) { return 'h' + level + '. ' + text; },
        bold: function (text) { return '*' + text + '*'; },
        italic: function (text) { return '_' + text + '_'; },
        inline: function (text) { return '{code}' + text + '{code}'; },
        code: function (text, lang) {
            return '{code' + (lang ? ':' + lang : '') + '}' + text + '{code}';
        },
        link: function (text, url) { return '[' + text + '|' + url + ']'; },
        panel: function (title, body, jiraOpts) {
            var open = '{panel' +
                (title ? ':title=' + title : '') +
                (jiraOpts ? (title ? '|' : ':') + jiraOpts : '') +
                '}';
            return open + body + '\n{panel}';
        }
    };
}

function forFlavor(flavor) {
    return flavor === 'markdown' ? markdownFlavor() : jiraFlavor();
}

function forTicket(ticketKey, customParams) {
    return forFlavor(flavorForTicket(ticketKey, customParams));
}

module.exports = {
    flavorForTicket: flavorForTicket,
    forFlavor: forFlavor,
    forTicket: forTicket
};

/**
 * Pre-CLI Rework Setup Action (preCliJSAction for pr_rework agent)
 * 1. Finds the existing PR for the ticket
 * 2. Checks out the PR branch
 * 3. Merges origin/{baseBranch} into the PR branch (auto-update, before setup commands run —
 *    see the comment above the detectMergeConflicts() call for why the order matters)
 * 4. Runs project-specific setup commands (build/verify) against the now-updated branch
 * 5. Writes input folder: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 *    plus the pinned gh-799 input contract: pr_discussions_raw.json (even with 0 threads),
 *    ci_failures.md (even with 0 failed checks) and review_state.md (review verdicts +
 *    decision state) — the complete open-item picture regardless of which armer fired.
 * 6. Fetches question subtasks with answers (extra context)
 * 7. Posts "Rework Started" comment to the ticket (Jira/ADO/GitHub via common/trackers.js),
 *    rendered in the ticket's markup flavor (Markdown on GitHub, wiki on Jira — gh-770)
 */

var configLoader = require('./configLoader.js');
var trackersModule = require('./common/trackers.js');
var commentMarkup = require('./common/commentMarkup.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const { resolveStatuses } = require('./config.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchParentContextToInput = require('./fetchParentContextToInput.js');
var restoreFromReleases = require('./restoreFromReleases.js');
var setupCommands = require('./common/setupCommands.js');
var baseBranchMarker = require('./common/baseBranchMarker.js');

/**
 * Optionally syncs the PR's base branch with its own upstream (config.git.baseBranch)
 * before merge-conflict detection runs. Relevant in two-branch mode, where the PR's base is
 * a long-lived branch (e.g. "release/rc_*") that can drift stale relative to
 * config.git.baseBranch over time. Delegates to a project-specific hook
 * (customParams.branchSyncFnPath) because syncing may require bypassing branch-protection
 * rules that block direct pushes to that branch — same rationale as
 * customParams.branchCreateFnPath in checkoutBranch.js.
