function postReviewToJira(tracker, ticketKey, reviewContent, reviewData, prUrl) {
    try {
        const m = commentMarkup.forTicket(ticketKey);
        let comment = m.h(2, '🔍 Automated PR Review Completed') + '\n\n';

        // Add outcome badge
