            head: headSha,
            verdict: verdict,
            blocking: issueCounts.blocking,
            important: issueCounts.important,
            suggestions: issueCounts.suggestions,
            source: 'pr_review.json'
        }, provider);
        if (!body) {
            console.warn('verdict record: unbuildable record (verdict ' + verdict + ') — not posted');
            return;
