        assert.ok(out.indexOf('h3. 🔧 Automated Rework Started\n') === 0, 'starts with the historical h3 heading');
        assert.ok(out.indexOf('*Pull Request*: [PR #1308|https://github.com/acme/widgets/pull/1308]\n') !== -1);
